import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

// ---------------------------------------------------------------------------
// Stage — shared three.js viewport for every 3D rig: renderer, orbit camera
// (drag + auto-rotate), warm sun + soft shadows, a textured grass ground, and
// a library of PROCEDURAL canvas textures (wood, metal, asphalt, foliage,
// fabric, concrete, grass, plastic) that are UV-mapped with RepeatWrapping and
// paired bump maps for surface relief. No external image assets required.
// ---------------------------------------------------------------------------

export type TexName =
  | 'wood'
  | 'metal'
  | 'asphalt'
  | 'leaf'
  | 'fabric'
  | 'concrete'
  | 'grass'
  | 'plastic';

// ---- colour helpers ----
function toRGB(hex: number): [number, number, number] {
  return [(hex >> 16) & 255, (hex >> 8) & 255, hex & 255];
}
function cl(v: number) {
  return Math.max(0, Math.min(255, v | 0));
}
function shade(hex: number, amt: number, sat = 1) {
  const [r, g, b] = toRGB(hex);
  return `rgb(${cl(r + amt)},${cl(g + amt * sat)},${cl(b + amt)})`;
}

// ---- procedural texture drawing (returns an HTMLCanvasElement) ----
function drawTexture(name: TexName, color: number, S = 128): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = c.height = S;
  const x = c.getContext('2d')!;
  const [r, g, b] = toRGB(color);
  x.fillStyle = `rgb(${r},${g},${b})`;
  x.fillRect(0, 0, S, S);
  const rnd = (a: number, bb: number) => a + Math.random() * (bb - a);

  if (name === 'wood') {
    for (let i = 0; i < 90; i++) {
      x.strokeStyle = shade(color, rnd(-26, 14));
      x.lineWidth = rnd(0.5, 1.6);
      const y = rnd(0, S);
      x.beginPath();
      x.moveTo(0, y);
      for (let px = 0; px <= S; px += 8) x.lineTo(px, y + Math.sin(px * 0.08 + i) * 1.5);
      x.stroke();
    }
    for (let p = 0; p <= S; p += S / 4) {
      x.strokeStyle = shade(color, -34);
      x.lineWidth = 1.5;
      x.beginPath();
      x.moveTo(0, p);
      x.lineTo(S, p);
      x.stroke();
    }
    for (let k = 0; k < 3; k++) {
      x.strokeStyle = shade(color, -30);
      x.beginPath();
      x.ellipse(rnd(0, S), rnd(0, S), rnd(2, 5), rnd(3, 7), 0, 0, Math.PI * 2);
      x.stroke();
    }
  } else if (name === 'metal') {
    for (let i = 0; i < 160; i++) {
      x.strokeStyle = shade(color, rnd(-22, 30));
      x.lineWidth = rnd(0.4, 1);
      const y = rnd(0, S);
      x.beginPath();
      x.moveTo(0, y);
      x.lineTo(S, y);
      x.stroke();
    }
  } else if (name === 'asphalt') {
    for (let i = 0; i < 2600; i++) {
      x.fillStyle = shade(color, rnd(-34, 34));
      const s = rnd(0.6, 2.2);
      x.fillRect(rnd(0, S), rnd(0, S), s, s);
    }
  } else if (name === 'leaf') {
    for (let i = 0; i < 320; i++) {
      x.fillStyle = shade(color, rnd(-40, 34), 1.3);
      x.beginPath();
      x.arc(rnd(0, S), rnd(0, S), rnd(2.5, 7), 0, Math.PI * 2);
      x.fill();
    }
  } else if (name === 'fabric') {
    for (let p = 0; p < S; p += 3) {
      x.strokeStyle = shade(color, 12);
      x.globalAlpha = 0.35;
      x.beginPath();
      x.moveTo(p, 0);
      x.lineTo(p, S);
      x.stroke();
      x.strokeStyle = shade(color, -16);
      x.beginPath();
      x.moveTo(0, p);
      x.lineTo(S, p);
      x.stroke();
    }
    x.globalAlpha = 1;
  } else if (name === 'concrete') {
    for (let i = 0; i < 1800; i++) {
      x.fillStyle = shade(color, rnd(-18, 22));
      x.fillRect(rnd(0, S), rnd(0, S), 1, 1);
    }
  } else if (name === 'grass') {
    for (let i = 0; i < 2200; i++) {
      x.strokeStyle = shade(color, rnd(-30, 26), 1.4);
      x.lineWidth = 1;
      const gx = rnd(0, S);
      const gy = rnd(0, S);
      x.beginPath();
      x.moveTo(gx, gy);
      x.lineTo(gx + rnd(-1.5, 1.5), gy - rnd(2, 5));
      x.stroke();
    }
  } else if (name === 'plastic') {
    const grad = x.createLinearGradient(0, 0, 0, S);
    grad.addColorStop(0, shade(color, 30));
    grad.addColorStop(0.5, shade(color, 4));
    grad.addColorStop(1, shade(color, -22));
    x.fillStyle = grad;
    x.fillRect(0, 0, S, S);
    for (let i = 0; i < 400; i++) {
      x.fillStyle = shade(color, rnd(-8, 8));
      x.fillRect(rnd(0, S), rnd(0, S), 1, 1);
    }
  }
  return c;
}

const _texCache = new Map<string, THREE.CanvasTexture>();
function getTex(three: typeof THREE, name: TexName, color: number, rx: number, ry: number) {
  const key = `${name}:${color}:${rx}:${ry}`;
  const hit = _texCache.get(key);
  if (hit) return hit;
  const tex = new three.CanvasTexture(drawTexture(name, color));
  tex.wrapS = tex.wrapT = three.RepeatWrapping;
  tex.repeat.set(rx, ry);
  tex.anisotropy = 4;
  (tex as unknown as { colorSpace: string }).colorSpace = (three as unknown as { SRGBColorSpace: string }).SRGBColorSpace;
  _texCache.set(key, tex);
  return tex;
}

// ---- material + geometry helpers ----
export interface MatOpts {
  rough?: number;
  metal?: number;
  flat?: boolean;
  emissive?: number;
  opacity?: number;
  tex?: TexName;
  repeat?: [number, number];
  bump?: number;
}
export function mat(three: typeof THREE, color: number, o: MatOpts = {}) {
  const m = new three.MeshStandardMaterial({
    color: o.tex ? 0xffffff : color,
    roughness: o.rough ?? 0.82,
    metalness: o.metal ?? 0.0,
    flatShading: o.flat ?? false,
    emissive: o.emissive ?? 0x000000,
    transparent: o.opacity != null,
    opacity: o.opacity ?? 1,
  });
  if (o.tex) {
    const [rx, ry] = o.repeat ?? [1, 1];
    const t = getTex(three, o.tex, color, rx, ry);
    m.map = t;
    m.bumpMap = t;
    m.bumpScale = o.bump ?? 0.02;
  }
  return m;
}
export function box(
  three: typeof THREE,
  dims: [number, number, number],
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts & { rotX?: number; rotY?: number; rotZ?: number } = {},
) {
  const m = new three.Mesh(new three.BoxGeometry(...dims), mat(three, color, o));
  m.position.set(...pos);
  if (o.rotX) m.rotation.x = o.rotX;
  if (o.rotY) m.rotation.y = o.rotY;
  if (o.rotZ) m.rotation.z = o.rotZ;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
export function cyl(
  three: typeof THREE,
  rTop: number,
  rBot: number,
  h: number,
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts & { rotX?: number; rotY?: number; rotZ?: number; seg?: number } = {},
) {
  const m = new three.Mesh(new three.CylinderGeometry(rTop, rBot, h, o.seg ?? 16), mat(three, color, o));
  m.position.set(...pos);
  if (o.rotX) m.rotation.x = o.rotX;
  if (o.rotY) m.rotation.y = o.rotY;
  if (o.rotZ) m.rotation.z = o.rotZ;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
export function ball(
  three: typeof THREE,
  r: number,
  color: number,
  pos: [number, number, number] = [0, 0, 0],
  o: MatOpts = {},
) {
  const m = new three.Mesh(new three.IcosahedronGeometry(r, o.flat ? 1 : 3), mat(three, color, o));
  m.position.set(...pos);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

export type BuildFn = (three: typeof THREE, group: THREE.Group) => ((t: number) => void) | void;

export interface StageProps {
  build: BuildFn;
  height?: number;
  background?: string;
  autoRotate?: boolean;
  distance?: number;
  targetY?: number;
}

export function Stage({
  build,
  height = 340,
  background = '#9ec7d8',
  autoRotate = true,
  distance = 8,
  targetY = 0.7,
}: StageProps) {
  const ref = useRef<HTMLDivElement>(null);
  const buildRef = useRef(build);
  buildRef.current = build;

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let w = el.clientWidth || 480;
    const h = height;

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(w, h);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    el.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(background);
    scene.fog = new THREE.Fog(new THREE.Color(background).getHex(), distance * 2.2, distance * 4.5);

    const camera = new THREE.PerspectiveCamera(34, w / h, 0.1, 200);
    const target = new THREE.Vector3(0, targetY, 0);

    scene.add(new THREE.HemisphereLight(0xdff0ff, 0x6b7a55, 0.62));
    const sun = new THREE.DirectionalLight(0xfff0d6, 1.15);
    sun.position.set(6, 11, 5);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    const s = 7;
    sun.shadow.camera.left = -s;
    sun.shadow.camera.right = s;
    sun.shadow.camera.top = s;
    sun.shadow.camera.bottom = -s;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 40;
    sun.shadow.bias = -0.0004;
    scene.add(sun);

    // textured grass ground
    const groundMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 });
    groundMat.map = getTex(THREE, 'grass', 0x6f9e54, 24, 24);
    const ground = new THREE.Mesh(new THREE.CircleGeometry(distance * 1.6, 64), groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    const group = new THREE.Group();
    scene.add(group);
    const update = buildRef.current(THREE, group) || undefined;

    let az = Math.PI * 0.25;
    let el2 = Math.PI * 0.28;
    let dragging = false;
    let px = 0;
    let py = 0;
    const applyCam = () => {
      const r = distance;
      camera.position.set(
        target.x + r * Math.cos(el2) * Math.sin(az),
        target.y + r * Math.sin(el2),
        target.z + r * Math.cos(el2) * Math.cos(az),
      );
      camera.lookAt(target);
    };
    const dom = renderer.domElement;
    dom.style.cursor = 'grab';
    const down = (e: PointerEvent) => {
      dragging = true;
      px = e.clientX;
      py = e.clientY;
      dom.style.cursor = 'grabbing';
      dom.setPointerCapture(e.pointerId);
    };
    const move = (e: PointerEvent) => {
      if (!dragging) return;
      az -= (e.clientX - px) * 0.01;
      el2 = Math.max(0.08, Math.min(1.45, el2 + (e.clientY - py) * 0.01));
      px = e.clientX;
      py = e.clientY;
    };
    const up = (e: PointerEvent) => {
      dragging = false;
      dom.style.cursor = 'grab';
      try {
        dom.releasePointerCapture(e.pointerId);
      } catch {
        /* noop */
      }
    };
    dom.addEventListener('pointerdown', down);
    dom.addEventListener('pointermove', move);
    dom.addEventListener('pointerup', up);

    const clock = new THREE.Clock();
    let raf = 0;
    const loop = () => {
      const t = clock.getElapsedTime();
      if (autoRotate && !dragging) az += 0.0045;
      applyCam();
      if (update) update(t);
      renderer.render(scene, camera);
      raf = requestAnimationFrame(loop);
    };
    loop();

    const ro = new ResizeObserver(() => {
      w = el.clientWidth || w;
      renderer.setSize(w, h);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    });
    ro.observe(el);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      dom.removeEventListener('pointerdown', down);
      dom.removeEventListener('pointermove', move);
      dom.removeEventListener('pointerup', up);
      renderer.dispose();
      scene.traverse((obj) => {
        const anyObj = obj as unknown as {
          geometry?: THREE.BufferGeometry;
          material?: THREE.Material | THREE.Material[];
        };
        anyObj.geometry?.dispose?.();
        const m = anyObj.material;
        if (Array.isArray(m)) m.forEach((mm) => mm.dispose());
        else m?.dispose?.();
      });
      if (dom.parentNode === el) el.removeChild(dom);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return <div ref={ref} style={{ width: '100%', height, borderRadius: 12, overflow: 'hidden' }} />;
}

import React from 'react';
import * as THREE from 'three';
import { Stage, box, ball } from '../Stage';

// Shared peep builder — used by the Guest rig and seated inside the CoasterCar.
// Skin head with an actual face (eyes + brow + smile), brown hair, fabric-
// textured red shirt + navy trousers, brown shoes. Limbs are on pivots so it
// can either walk or sit. Returns the group plus a walk(t) animator.
export interface PeepOpts {
  shirt?: number;
  trousers?: number;
  seated?: boolean;
}
export function buildPeep(t: typeof THREE, o: PeepOpts = {}) {
  const SKIN = 0xe0a878;
  const HAIR = 0x4a3018;
  const SHIRT = o.shirt ?? 0xc21a1a;
  const TROU = o.trousers ?? 0x26305e;
  const SHOE = 0x2a1c10;
  const DARK = 0x1a1207;

  const grp = new t.Group();
  grp.add(box(t, [0.26, 0.14, 0.18], TROU, [0, 0.52, 0], { tex: 'fabric', repeat: [2, 1], rough: 0.9 }));
  grp.add(box(t, [0.3, 0.32, 0.2], SHIRT, [0, 0.74, 0], { tex: 'fabric', repeat: [2, 2], rough: 0.85 }));

  // head + face (faces +Z)
  const head = new t.Group();
  head.position.set(0, 0.99, 0);
  head.add(ball(t, 0.12, SKIN, [0, 0, 0], { rough: 0.7 }));
  const hair = ball(t, 0.128, HAIR, [0, 0.04, -0.012], { rough: 0.9 });
  hair.scale.set(1.02, 0.72, 1.02);
  head.add(hair);
  // eyes (white + pupil), brows, smile
  [-0.045, 0.045].forEach((ex) => {
    head.add(ball(t, 0.026, 0xffffff, [ex, 0.02, 0.104], { rough: 0.4 }));
    head.add(ball(t, 0.013, 0x1b1b22, [ex, 0.02, 0.121], { rough: 0.3 }));
    head.add(box(t, [0.05, 0.012, 0.01], HAIR, [ex, 0.062, 0.108], { rotZ: ex > 0 ? -0.15 : 0.15 }));
  });
  const smile = new t.Mesh(
    new t.TorusGeometry(0.035, 0.008, 8, 12, Math.PI),
    new t.MeshStandardMaterial({ color: DARK, roughness: 0.5 }),
  );
  smile.rotation.set(Math.PI, 0, 0);
  smile.position.set(0, -0.04, 0.108);
  head.add(smile);
  // nose
  head.add(ball(t, 0.018, SKIN, [0, -0.005, 0.12], { rough: 0.6 }));
  grp.add(head);

  const limb = (px: number, py: number, col: number, len: number, hand?: number, texd?: boolean) => {
    const pivot = new t.Group();
    pivot.position.set(px, py, 0);
    pivot.add(box(t, [0.09, len, 0.11], col, [0, -len / 2, 0], texd ? { tex: 'fabric', repeat: [1, 2], rough: 0.85 } : { rough: 0.7 }));
    if (hand != null) pivot.add(ball(t, 0.05, hand, [0, -len, 0], { rough: 0.7 }));
    grp.add(pivot);
    return pivot;
  };
  const armL = limb(-0.19, 0.88, SHIRT, 0.32, SKIN, true);
  const armR = limb(0.19, 0.88, SHIRT, 0.32, SKIN, true);
  const legL = limb(-0.08, 0.46, TROU, 0.4, undefined, true);
  const legR = limb(0.08, 0.46, TROU, 0.4, undefined, true);
  legL.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03], { rough: 0.6 }));
  legR.add(box(t, [0.12, 0.07, 0.2], SHOE, [0, -0.4, 0.03], { rough: 0.6 }));

  if (o.seated) {
    // thighs forward, shins down, arms resting forward
    legL.rotation.x = -1.5;
    legR.rotation.x = -1.5;
    armL.rotation.x = -1.1;
    armR.rotation.x = -1.1;
  }

  const walk = (time: number) => {
    const s = Math.sin(time * 5);
    legL.rotation.x = s * 0.5;
    legR.rotation.x = -s * 0.5;
    armL.rotation.x = -s * 0.45;
    armR.rotation.x = s * 0.45;
    grp.position.y = Math.abs(Math.cos(time * 5)) * 0.03;
  };
  return { group: grp, walk, head };
}

export function Guest() {
  return (
    <Stage
      distance={3.1}
      targetY={0.6}
      build={(t, g) => {
        const peep = buildPeep(t, { shirt: 0xc21a1a, trousers: 0x26305e });
        g.add(peep.group);
        return (time) => peep.walk(time);
      }}
    />
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl } from '../Stage';
import { buildPeep } from '../Guest';

// A wooden-coaster car modelled from the RCT2 vehicle sprite: a rounded orange
// open tub (plastic-textured) on a brushed-metal chassis, seat backs, lap bars
// and four wheels — now seating two real peeps (pink / gold shirts, each with a
// face). Exported as a builder so WoodenCoaster can put a train on the track.
export function buildCoasterCar(t: typeof THREE): THREE.Group {
  const g = new t.Group();
  const ORANGE = 0xe0601a;
  const ORANGE_D = 0xb5480f;
  const DARK = 0x26262b;
  const SEAT = 0x1c1c20;

  g.add(box(t, [0.56, 0.12, 0.98], DARK, [0, 0.0, 0], { tex: 'metal', repeat: [3, 4], metal: 0.7, rough: 0.5 }));
  g.add(box(t, [0.62, 0.36, 1.02], ORANGE, [0, 0.24, 0], { tex: 'plastic', repeat: [2, 1], rough: 0.4 }));
  g.add(box(t, [0.66, 0.06, 1.04], ORANGE_D, [0, 0.42, 0], { tex: 'plastic', repeat: [3, 1], rough: 0.4 }));
  g.add(box(t, [0.48, 0.26, 0.88], SEAT, [0, 0.32, 0], { rough: 0.8 })); // hollow interior
  g.add(box(t, [0.62, 0.32, 0.22], ORANGE, [0, 0.24, 0.56], { rotX: -0.6, tex: 'plastic', repeat: [2, 1], rough: 0.4 })); // nose

  // seated peeps + seat backs + lap bars
  const shirts = [0xe060a0, 0xf0c020];
  const trousers = [0x2a2f6a, 0x3a2a1a];
  [-0.18, 0.24].forEach((z, i) => {
    g.add(box(t, [0.5, 0.22, 0.05], SEAT, [0, 0.37, z - 0.16], { rough: 0.85 })); // seat back
    const peep = buildPeep(t, { shirt: shirts[i], trousers: trousers[i], seated: true });
    peep.group.scale.setScalar(0.62);
    peep.group.position.set(0, 0.06, z);
    g.add(peep.group);
    g.add(box(t, [0.36, 0.04, 0.04], DARK, [0, 0.5, z + 0.16], { tex: 'metal', metal: 0.6, rough: 0.35 })); // lap bar
  });

  const wheel = (x: number, z: number) =>
    cyl(t, 0.1, 0.1, 0.07, 0x1a1a1e, [x, -0.03, z], { rotZ: Math.PI / 2, tex: 'metal', repeat: [4, 1], metal: 0.6, rough: 0.4, seg: 20 });
  [
    [-0.31, 0.34],
    [0.31, 0.34],
    [-0.31, -0.34],
    [0.31, -0.34],
  ].forEach(([x, z]) => g.add(wheel(x, z)));

  return g;
}

export function CoasterCar() {
  return (
    <Stage
      distance={4.4}
      targetY={0.5}
      build={(t, g) => {
        const TIE = 0x6b4626;
        for (let z = -1.4; z <= 1.4; z += 0.4) g.add(box(t, [0.98, 0.06, 0.12], TIE, [0, 0.02, z], { tex: 'wood', repeat: [3, 1], rough: 0.9 }));
        g.add(box(t, [0.07, 0.08, 3.0], 0x8b8f96, [-0.32, 0.09, 0], { tex: 'metal', repeat: [1, 20], metal: 0.85, rough: 0.3 }));
        g.add(box(t, [0.07, 0.08, 3.0], 0x8b8f96, [0.32, 0.09, 0], { tex: 'metal', repeat: [1, 20], metal: 0.85, rough: 0.3 }));
        const car = buildCoasterCar(t);
        car.position.y = 0.2;
        g.add(car);
        return (time) => {
          car.position.y = 0.2 + Math.sin(time * 2) * 0.02;
          car.rotation.z = Math.sin(time * 1.3) * 0.02;
        };
      }}
    />
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, box } from '../Stage';
import { buildCoasterCar } from '../CoasterCar';

// A straight run of wooden roller-coaster track modelled from the RCT2 sprite:
// two brushed-steel rails on wood-grain stringers over cross-ties, carried by
// wooden support bents (posts + ledgers + X cross-braces). A two-car train of
// peep-filled cars rides the length on a loop.
export function WoodenCoaster() {
  return (
    <Stage
      distance={9}
      targetY={1.0}
      build={(t, g) => {
        const WOOD = 0x7a5230;
        const WOOD_D = 0x5f3f24;
        const RAIL = 0x8b8f96;
        const TIE = 0x6b4626;
        const L = 6;
        const y = 1.25;

        g.add(box(t, [0.16, 0.2, L], WOOD, [-0.34, y - 0.18, 0], { tex: 'wood', repeat: [1, 10], rough: 0.9 }));
        g.add(box(t, [0.16, 0.2, L], WOOD, [0.34, y - 0.18, 0], { tex: 'wood', repeat: [1, 10], rough: 0.9 }));
        for (let z = -L / 2 + 0.2; z <= L / 2 - 0.2; z += 0.5)
          g.add(box(t, [1.02, 0.06, 0.14], TIE, [0, y - 0.05, z], { tex: 'wood', repeat: [4, 1], rough: 0.9 }));
        g.add(box(t, [0.07, 0.09, L], RAIL, [-0.34, y + 0.05, 0], { tex: 'metal', repeat: [1, 30], metal: 0.85, rough: 0.3 }));
        g.add(box(t, [0.07, 0.09, L], RAIL, [0.34, y + 0.05, 0], { tex: 'metal', repeat: [1, 30], metal: 0.85, rough: 0.3 }));

        const brace = Math.atan2(y, 1.1);
        const bent = (z: number) => {
          const b = new t.Group();
          [-0.55, 0.55].forEach((x) =>
            b.add(box(t, [0.14, y, 0.14], WOOD, [x, y / 2, 0], { tex: 'wood', repeat: [1, 6], rough: 0.9 })),
          );
          b.add(box(t, [1.42, 0.12, 0.12], WOOD_D, [0, 0.28, 0], { tex: 'wood', repeat: [6, 1], rough: 0.9 }));
          b.add(box(t, [1.42, 0.12, 0.12], WOOD_D, [0, y - 0.18, 0], { tex: 'wood', repeat: [6, 1], rough: 0.9 }));
          b.add(box(t, [1.55, 0.06, 0.05], WOOD_D, [0, y / 2, 0], { rotZ: brace, tex: 'wood', repeat: [6, 1] }));
          b.add(box(t, [1.55, 0.06, 0.05], WOOD_D, [0, y / 2, 0], { rotZ: -brace, tex: 'wood', repeat: [6, 1] }));
          b.position.z = z;
          g.add(b);
        };
        [-2.2, -0.7, 0.7, 2.2].forEach(bent);

        const cars = [buildCoasterCar(t), buildCoasterCar(t)];
        cars.forEach((c) => {
          c.scale.setScalar(0.92);
          g.add(c);
        });
        const span = L + 2;
        return (time) => {
          const head = ((time * 1.4) % span) - span / 2;
          cars.forEach((c, i) => c.position.set(0, y + 0.16, head - i * 0.95));
        };
      }}
    />
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, cyl, ball } from '../Stage';

// An oak tree modelled from the RCT2 scenery sprite: a wood-grain trunk under a
// cluster of chunky, leaf-textured olive/green foliage blobs. Sways gently.
export function OakTree() {
  return (
    <Stage
      distance={6}
      targetY={1.2}
      build={(t, g) => {
        const BARK = 0x5a3d22;
        const greens = [0x6f8f3a, 0x5c7d2e, 0x86a84a, 0x7c9a40];
        const tree = new t.Group();
        g.add(tree);
        tree.add(cyl(t, 0.14, 0.2, 1.1, BARK, [0, 0.55, 0], { tex: 'wood', repeat: [3, 3], rough: 1 }));
        const blobs: [number, number, number, number, number][] = [
          [0, 1.55, 0, 0.74, greens[0]],
          [-0.52, 1.36, 0.18, 0.52, greens[1]],
          [0.5, 1.42, -0.12, 0.56, greens[2]],
          [0.12, 1.9, -0.05, 0.52, greens[3]],
          [-0.22, 1.58, -0.46, 0.46, greens[1]],
          [0.36, 1.64, 0.42, 0.47, greens[2]],
          [-0.05, 1.28, 0.5, 0.44, greens[0]],
        ];
        blobs.forEach(([x, y, z, r, c]) =>
          tree.add(ball(t, r, c, [x, y, z], { tex: 'leaf', repeat: [3, 3], flat: true, rough: 1 })),
        );
        return (time) => {
          tree.rotation.z = Math.sin(time * 1.1) * 0.025;
          tree.rotation.x = Math.cos(time * 0.9) * 0.02;
        };
      }}
    />
  );
}

import React from 'react';
import { Stage, box } from '../Stage';

// A paved park road tile modelled from the RCT2 tarmac footpath: an aggregate
// asphalt slab (textured) with light concrete kerbs on two edges and a dashed
// centre line.
export function Road() {
  return (
    <Stage
      distance={4.6}
      targetY={0.15}
      build={(t, g) => {
        const ASP = 0x6b6b6e;
        const KERB = 0xb9b6ad;
        const LINE = 0xe8c64a;
        g.add(box(t, [2.0, 0.12, 2.0], ASP, [0, 0.06, 0], { tex: 'asphalt', repeat: [4, 4], rough: 0.97, bump: 0.03 }));
        g.add(box(t, [2.0, 0.16, 0.12], KERB, [0, 0.1, 0.98], { tex: 'concrete', repeat: [8, 1], rough: 0.9 }));
        g.add(box(t, [2.0, 0.16, 0.12], KERB, [0, 0.1, -0.98], { tex: 'concrete', repeat: [8, 1], rough: 0.9 }));
        for (let x = -0.8; x <= 0.8; x += 0.5) g.add(box(t, [0.3, 0.02, 0.08], LINE, [x, 0.13, 0], { rough: 0.6 }));
      }}
    />
  );
}
